package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
public class AutonomousStageRouteTest {
 @Test public void oneActualReentryPermitsOneContinuation(){Object run=new Object();var r=new AutonomousStageRoute(run);assertTrue(r.requestRestore(run,true));assertTrue(r.onStart(run,true));var c=r.claimSecond(run,true,true);assertNotNull(c);assertTrue(r.consume(c,run,true));assertFalse(r.consume(c,run,true));assertNull(r.claimSecond(run,true,true));assertFalse(r.pending());}
 @Test public void initialVisibleResumeDoesNotAuthorizeSecond(){Object run=new Object();var r=new AutonomousStageRoute(run);assertFalse(r.onStart(run,true));assertNull(r.claimSecond(run,true,true));}
 @Test public void osReturnAloneDoesNotAuthorizeSecond(){Object run=new Object();var r=new AutonomousStageRoute(run);assertTrue(r.requestRestore(run,true));assertNull(r.claimSecond(run,true,true));assertTrue(r.pending());}
 @Test public void restoreRequestCannotRepeat(){Object run=new Object();var r=new AutonomousStageRoute(run);assertTrue(r.requestRestore(run,true));assertFalse(r.requestRestore(run,true));}
 @Test public void unpublishedUnknownOrNoReturnCannotRequest(){Object run=new Object();var r=new AutonomousStageRoute(run);assertFalse(r.requestRestore(run,false));assertFalse(r.pending());assertNull(r.claimSecond(run,true,true));}
 @Test public void differentRunCannotRequestOrResume(){Object run=new Object();var r=new AutonomousStageRoute(run);assertFalse(r.requestRestore(new Object(),true));assertTrue(r.requestRestore(run,true));assertFalse(r.onStart(new Object(),true));assertNull(r.claimSecond(run,true,true));}
 @Test public void expiredAtReentryCannotAdvance(){Object run=new Object();var r=new AutonomousStageRoute(run);assertTrue(r.requestRestore(run,true));assertFalse(r.onStart(run,false));assertNull(r.claimSecond(run,true,true));}
 @Test public void onStartWithoutFocusedResumeIsNotApproval(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);r.onStart(run,true);assertNull(r.claimSecond(run,false,true));assertNotNull(r.claimSecond(run,true,true));}
 @Test public void expiredBeforeVisibleApprovalCannotAdvance(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);r.onStart(run,true);assertNull(r.claimSecond(run,true,false));}
 @Test public void cancelAfterRestoreCannotRecover(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);r.cancel();assertFalse(r.onStart(run,true));assertFalse(r.requestRestore(run,true));assertNull(r.claimSecond(run,true,true));}
 @Test public void cancelAfterClaimInvalidatesToken(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);r.onStart(run,true);var c=r.claimSecond(run,true,true);r.cancel();assertFalse(r.consume(c,run,true));}
 @Test public void expiryAtConsumeIsPermanentlySpent(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);r.onStart(run,true);var c=r.claimSecond(run,true,true);assertFalse(r.consume(c,run,false));assertFalse(r.consume(c,run,true));}
 @Test public void otherActivityRouteCannotReplayToken(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);r.onStart(run,true);var c=r.claimSecond(run,true,true);var replacement=new AutonomousStageRoute(run);replacement.requestRestore(run,true);replacement.onStart(run,true);replacement.claimSecond(run,true,true);assertFalse(replacement.consume(c,run,true));}
 @Test public void duplicateOnStartDoesNotGrantAnotherToken(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);assertTrue(r.onStart(run,true));assertFalse(r.onStart(run,true));assertNotNull(r.claimSecond(run,true,true));assertFalse(r.onStart(run,true));assertNull(r.claimSecond(run,true,true));}
 @Test public void nullOrWrongRunTokenCannotConsume(){Object run=new Object();var r=new AutonomousStageRoute(run);r.requestRestore(run,true);r.onStart(run,true);var c=r.claimSecond(run,true,true);assertFalse(r.consume(null,run,true));assertFalse(r.consume(c,new Object(),true));assertTrue(r.consume(c,run,true));}
}
